62	func (s *APIV1Service) GetIdentityProvider(ctx context.Context, request *v1pb.GetIdentityProviderRequest) (*v1pb.IdentityProvider, error) {
63		uid, err := ExtractIdentityProviderUIDFromName(request.Name)
64		if err != nil {
65			return nil, status.Errorf(codes.InvalidArgument, "invalid identity provider name: %v", err)
66		}
67		identityProvider, err := s.Store.GetIdentityProvider(ctx, &store.FindIdentityProvider{
68			UID: &uid,
69		})
70		if err != nil {
71			return nil, status.Errorf(codes.Internal, "failed to get identity provider, error: %+v", err)
72		}
73		if identityProvider == nil {
74			return nil, status.Errorf(codes.NotFound, "identity provider not found")
75		}
76	
77		return convertIdentityProviderFromStore(identityProvider), nil
78	}
